begin;
set local statement_timeout='10s';
create function pg_temp.check_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'SECURITY_ASSERTION: %',label;end if;end;$$;
select pg_temp.check_assert(not has_function_privilege('anon','public.scanner_validation_admit_v1(text,text,text,uuid)','execute'),'anon execute denied');
select pg_temp.check_assert(not has_function_privilege('authenticated','public.scanner_validation_admit_v2(text,text,text,uuid,text,text,text)','execute'),'authenticated execute denied');
select pg_temp.check_assert(not has_schema_privilege('anon','scanner_security_validation','usage'),'private schema denied');
select pg_temp.check_assert(not has_table_privilege('service_role','scanner_security_validation.release_approvals','insert,update,delete'),'app cannot grant production approval');
select pg_temp.check_assert(not has_table_privilege('service_role','scanner_security_validation.policy','insert,update,delete'),'app cannot raise quotas');
select pg_temp.check_assert((select bool_and(relrowsecurity) from pg_class where relnamespace='scanner_security_validation'::regnamespace and relkind='r'),'all quota tables have RLS');
select pg_temp.check_assert((select bool_and(not prosecdef and proconfig=array['search_path=pg_catalog']) from pg_proc where pronamespace='public'::regnamespace and proname like 'scanner_validation_%'),'functions are invoker with fixed search path');
do $$declare r jsonb;vid uuid:=gen_random_uuid();key text:=repeat('a',64);client text:=repeat('b',64);i integer;id2 uuid;sec bigint:=floor(extract(epoch from clock_timestamp()));begin
 r:=public.scanner_validation_admit_v1('bad',key,'token-current',vid);perform pg_temp.check_assert(r->>'status'='INVALID','malformed identity');
 r:=public.scanner_validation_admit_v1(client,key,'token-current',vid);perform pg_temp.check_assert(r->>'status'='ADMITTED','normal admission');
 r:=public.scanner_validation_admit_v1(client,key,'token-current',gen_random_uuid());perform pg_temp.check_assert(r->>'status'='DUPLICATE','duplicate operation');
 perform pg_temp.check_assert(public.scanner_validation_finish_v1(vid,'{"observedAt":"2026-11-26T05:23:00Z"}',200),'finish lease');
 r:=public.scanner_validation_admit_v1(client,key,'token-current',gen_random_uuid());perform pg_temp.check_assert(r->>'status'='CACHED' and r->'body'->>'observedAt'='2026-11-26T05:23:00Z','cache retains original observation');
 delete from scanner_security_validation.response_cache;
 r:=public.scanner_validation_admit_v1(client,key,'token-current',vid);
 for i in 1..4 loop r:=public.scanner_validation_debit_v1(vid,'rpc','alchemy',1);perform pg_temp.check_assert(r->>'status'='ADMITTED','provider debit permitted');end loop;
 r:=public.scanner_validation_debit_v1(vid,'rpc','alchemy',1);perform pg_temp.check_assert(r->>'status'='REQUEST_BUDGET','request cap');
 perform public.scanner_validation_finish_v1(vid,null,503);
 delete from scanner_security_validation.counters;
 insert into scanner_security_validation.counters values('client',client,60,sec/60,60);
 r:=public.scanner_validation_admit_v1(client,key,'token-current',vid);perform pg_temp.check_assert(r->>'status'='RATE_LIMIT' and (r->>'retryAfter')::integer between 1 and 60,'client exhaustion and retry');
 update scanner_security_validation.counters set bucket=bucket-1;
 r:=public.scanner_validation_admit_v1(client,key,'token-current',vid);perform pg_temp.check_assert(r->>'status'='ADMITTED','quota window recovery');
 update scanner_security_validation.leases set expires_at=clock_timestamp()-interval '1 second' where scanner_security_validation.leases.id=vid;
 r:=public.scanner_validation_debit_v1(vid,'rpc','alchemy',1);perform pg_temp.check_assert(r->>'status'='LEASE_EXPIRED','expired lease denies outbound');
 delete from scanner_security_validation.leases;delete from scanner_security_validation.counters;
 for i in 1..8 loop r:=public.scanner_validation_admit_v1(client,md5(i::text)||md5(i::text),'token-current',gen_random_uuid());perform pg_temp.check_assert(r->>'status'='ADMITTED','client active fixture');end loop;
 r:=public.scanner_validation_admit_v1(client,repeat('c',64),'token-current',gen_random_uuid());perform pg_temp.check_assert(r->>'status'='CONCURRENT_LIMIT','per-client concurrency');
 delete from scanner_security_validation.leases;delete from scanner_security_validation.counters;
 for i in 1..24 loop r:=public.scanner_validation_admit_v1(md5(i::text)||md5(i::text),md5(i::text)||md5(i::text),'token-current',gen_random_uuid());perform pg_temp.check_assert(r->>'status'='ADMITTED','global active fixture');end loop;
 r:=public.scanner_validation_admit_v1(client,key,'token-current',gen_random_uuid());perform pg_temp.check_assert(r->>'status'='CONCURRENT_LIMIT','cross-client global concurrency');
 delete from scanner_security_validation.leases;delete from scanner_security_validation.counters;
 r:=public.scanner_validation_admit_v1(client,key,'holder-scan-worker',vid);perform pg_temp.check_assert(r->>'status'='ADMITTED','worker admission');
 r:=public.scanner_validation_admit_v1(repeat('d',64),repeat('e',64),'holder-scan-tick',gen_random_uuid());perform pg_temp.check_assert(r->>'status'='CONCURRENT_LIMIT','one worker globally');
 delete from scanner_security_validation.leases;delete from scanner_security_validation.counters;
 r:=public.scanner_validation_admit_v1(client,key,'token-current',vid);
 sec:=floor(extract(epoch from clock_timestamp()));insert into scanner_security_validation.counters values('rpc','global',60,sec/60,120);
 r:=public.scanner_validation_debit_v1(vid,'rpc','alchemy',1);perform pg_temp.check_assert(r->>'status'='PROVIDER_BUDGET','global RPC minute cap');
 delete from scanner_security_validation.counters;insert into scanner_security_validation.counters values('provider','helius',60,sec/60,30);
 r:=public.scanner_validation_debit_v1(vid,'rpc','helius',1);perform pg_temp.check_assert(r->>'status'='PROVIDER_BUDGET','Helius capacity');
 delete from scanner_security_validation.counters;insert into scanner_security_validation.counters values('rpc','global',86400,sec/86400,6000);
 r:=public.scanner_validation_debit_v1(vid,'rpc','alchemy',1);perform pg_temp.check_assert(r->>'status'='PROVIDER_BUDGET','global RPC day cap');
 r:=public.scanner_validation_admit_v2(client,key,'token-current',gen_random_uuid(),'production',repeat('1',40),'dpl_validation00001');perform pg_temp.check_assert(r->>'status'='RELEASE_NOT_AUTHORIZED','unreviewed production denies even cache hits');
 insert into scanner_security_validation.release_approvals values(repeat('1',40),'dpl_validation00001','prj_AbsbiTw8Kc8axGpZ3FFpH9VvDS4e','integration/glitch-app-main-20261118','doom404official-collab',1,2,3,true,clock_timestamp(),clock_timestamp()+interval '5 minutes');
 r:=public.scanner_validation_admit_v2(client,repeat('f',64),'token-current',gen_random_uuid(),'production',repeat('2',40),'dpl_validation00001');perform pg_temp.check_assert(r->>'status'='RELEASE_NOT_AUTHORIZED','mismatched SHA denies');
 r:=public.scanner_validation_admit_v2(client,repeat('f',64),'token-current',gen_random_uuid(),'production',repeat('1',40),'dpl_validation00002');perform pg_temp.check_assert(r->>'status'='RELEASE_NOT_AUTHORIZED','mismatched deployment denies');
 r:=public.scanner_validation_admit_v2(client,repeat('f',64),'token-current',gen_random_uuid(),'production',repeat('1',40),'dpl_validation00001');perform pg_temp.check_assert(r->>'status'='ADMITTED','exact approved release admitted in isolated fixture');
end $$;
rollback;
select jsonb_build_object('status','PASS','suite','isolated real PostgreSQL admission, quotas, privileges, production authorization','provider_requests',0,'fixture_changes_rolled_back',true) receipt;
